package cl.nexbyte.siger.institucional.nucleo;
import java.nio.file.Path;import java.time.Clock;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import cl.nexbyte.siger.institucional.robustez.FalloTecnico;import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
class EquipoDocumentosTest {
 @TempDir Path temp;ContenidoFixture x;
 @BeforeEach void setup()throws Exception{x=new ContenidoFixture(temp,Clock.systemUTC(),null);}
 @AfterEach void close()throws Exception{if(x!=null)x.close();}
 @Test void colaboracionPermiteDocumentoOrdinarioPeroNoFirNiExpedienteAjeno(){var f=x.f;var cas=x.m.caso();var doc=x.cargar(cas).id();x.c().proteger(f.a(f.headA),UUID.randomUUID(),cas,doc,new ContenidoInstitucional.Proteccion(0,"ORDINARIO","Documento ordinario del equipo"));f.core.equipo().incorporar(f.a(f.profA),UUID.randomUUID(),cas,new EquipoCaso.Incorporar(f.core.caso(f.a(f.profA),cas).revision(),f.profB,"Apoyo local"));assertNotNull(x.docs.referencia(f.a(f.profB),cas,doc));var sinClasificar=x.cargar(cas).id();assertEquals(404,assertThrows(FalloTecnico.class,()->x.docs.referencia(f.a(f.profB),cas,sinClasificar)).status);x.d.db.sql.update("DELETE FROM document_content_policy WHERE document_id=?",sinClasificar.toString());assertEquals(404,assertThrows(FalloTecnico.class,()->x.docs.referencia(f.a(f.profB),cas,sinClasificar)).status);assertNotNull(x.docs.referencia(f.a(f.profA),cas,sinClasificar));assertEquals(1,x.docs.listar(f.a(f.profB),cas).size());x.c().proteger(f.a(f.headA),UUID.randomUUID(),cas,doc,new ContenidoInstitucional.Proteccion(1,"FIR","Contenido reservado específico"));assertTrue(x.docs.listar(f.a(f.profB),cas).isEmpty());assertEquals(404,assertThrows(FalloTecnico.class,()->x.docs.referencia(f.a(f.profB),cas,doc)).status);assertNotNull(x.docs.referencia(f.a(f.profA),cas,doc));assertEquals(404,assertThrows(FalloTecnico.class,()->f.core.equipo().ver(f.a(x.m.upr),cas)).status);}
 @Test void miembroDeOtraAreaRequiereFacultadExplicitaYRetiroCierraDocumentos()throws Exception{var f=x.f;var cas=x.m.caso();String outsider=f.user("col.otra.area");vincular(outsider,"p-"+outsider);f.otorgar(outsider,"PROFESIONAL","AREA_B");assertEquals(400,assertThrows(FalloTecnico.class,()->f.core.equipo().incorporar(f.a(f.headA),UUID.randomUUID(),cas,new EquipoCaso.Incorporar(0,outsider,"No equivale a todo UPR"))).status);f.otorgar(outsider,"PROFESIONAL","AREA_A");f.core.equipo().incorporar(f.a(f.headA),UUID.randomUUID(),cas,new EquipoCaso.Incorporar(0,outsider,"Acreditado en ámbito local"));var doc=x.docs.cargar(f.a(outsider),UUID.randomUUID(),cas,null,"aporte.txt",new java.io.ByteArrayInputStream("Aporte sintético".getBytes(java.nio.charset.StandardCharsets.UTF_8))).id();assertNotNull(x.docs.referencia(f.a(outsider),cas,doc));f.core.equipo().retirar(f.a(f.headA),UUID.randomUUID(),cas,new EquipoCaso.Retirar(f.core.caso(f.a(f.headA),cas).revision(),outsider,null,"Finaliza apoyo"));assertEquals(404,assertThrows(FalloTecnico.class,()->x.docs.listar(f.a(outsider),cas)).status);assertEquals(1,f.core.caso(f.a(f.headA),cas).asignaciones().size());}
 void vincular(String actor,String persona)throws Exception{var f=x.f;var r=x.d.mapper.readValue(Base64.getDecoder().decode(x.d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch ORDER BY revision DESC LIMIT 1",String.class)),cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro12.class);var bindings=new ArrayList<>(r.vinculos());bindings.add(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Vinculo(actor,persona,f.start,f.end,ConcesionFixture.huella(x.d.db,actor)));f.importar(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro12("1.2",r.revision()+1,x.clock.instant(),r.expira(),bindings,r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea(),r.materias(),r.sedesRegionales(),r.ambitosMateria()));}
 @Test void cuentaAliasNoHeredaPertenenciaAunqueSeaLaMismaPersona()throws Exception{var f=x.f;var cas=x.m.caso();String alias=f.user("alias.colaborador");vincular(alias,"p-"+f.profB);f.otorgar(alias,"PROFESIONAL","AREA_A");f.core.equipo().incorporar(f.a(f.headA),UUID.randomUUID(),cas,new EquipoCaso.Incorporar(0,f.profB,"Colaboración personal acreditada"));assertNotNull(f.core.caso(f.a(f.profB),cas));assertEquals(404,assertThrows(FalloTecnico.class,()->f.core.caso(f.a(alias),cas)).status);assertEquals(0,f.core.casos(f.a(alias),"",0,20).total());assertEquals(404,assertThrows(FalloTecnico.class,()->x.docs.listar(f.a(alias),cas)).status);}
}
